import{z as A,x as B,o as t,c as p,q as n,j as s,D as E,d as r,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"SMT 求解器","description":"","frontmatter":{"title":"SMT 求解器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/smt-solver.md","filePath":"cs/smt-solver.md","lastUpdated":1791063341000}'),d={name:"cs/smt-solver.md"};function m(T,a,S,h,D,u){const l=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="smt-求解器" tabindex="-1">SMT 求解器 <a class="header-anchor" href="#smt-求解器" aria-label="Permalink to &quot;SMT 求解器&quot;">​</a></h1><div class="epigraph"><p>SAT 模理论：命题骨架仍由 CDCL 管，算术、数组、位向量各有判定器，通过理论传播与冲突把等式送回布尔层。Nelson–Oppen 组合无量词的稳定理论。</p><footer>—— 据 Nelson and Oppen, 1979；Barrett et al., SMT-LIB；Kroening and Strichman 整理</footer></div><p>上一课<a href="/cs/dpll-cdcl">CDCL</a> 只懂 0-1 子句。Hoare 的 VC 含 \\(i+1\\lt n\\)、数组读。缺口是 <strong>SMT</strong>：\\(\\mathrm{QF\\_LIA}\\)、\\(\\mathrm{QF\\_BV}\\)、数组。本课钉 DPLL(T) 形状，不把一阶完全性请回来——带量词的碎片许多不可判定，求解器靠实例化启发式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原子可以是 \\(x+y\\le 3\\)、\\(a[i]=v\\)。布尔结构仍 CNF。理论求解器 \\(T\\)：给定文字集，判定合取是否 \\(T\\)-可满足，并推出更多文字（传播）或解释。冲突：理论不可满足的核，学布尔子句。等式共享用 E-图（Congruence closure）。Nelson–Oppen：稳定、无量词、签名不交的理论，靠等式交换组合。</p><p>位向量：本质是 SAT 爆破或位级传播，规模随位宽。</p><h3 id="不是「prolog」" tabindex="-1">不是「Prolog」 <a class="header-anchor" href="#不是「prolog」" aria-label="Permalink to &quot;不是「Prolog」&quot;">​</a></h3><p>SMT 主要无量词或有限实例化。Horn 子句、Prolog 是另一搜索。Z3 能跑的量词是 E-matching，不完备。</p><p><span class="marginnote">Nelson–Oppen 1979。DPLL(T)：Nieuwenhuis、Oliveras、Tinelli。SMT-LIB 标准。Kroening–Strichman 教材。本课不写 Simplex 全部枢轴。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>举 \\(x=y\\land f(x)\\ne f(y)\\) 的冲突（同余）。举线性不等式与布尔开关。指出：不可判定理论被切成可判定的 QF 碎片。对照<a href="/cs/predicate-logic">谓词逻辑</a> 的一般不可判定：SMT 活在可判定岛上。</p>',11)),(t(),s(i,null,{default:E(()=>[o(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOL%5B%22CDCL%20%E5%B8%83%E5%B0%94%E9%AA%A8%E6%9E%B6%22%5D%20--%3E%20T%5B%22%E7%90%86%E8%AE%BA%E6%B1%82%E8%A7%A3%E5%99%A8%22%5D%0A%20%20T%20--%3E%20PROP%5B%22%E4%BC%A0%E6%92%AD%E6%96%87%E5%AD%97%20%2F%20%E5%86%B2%E7%AA%81%E6%A0%B8%22%5D%0A%20%20PROP%20--%3E%20BOOL%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"程序验证：wp 生成一阶 VC，量化数组用选择公理图式实例化，落到 QF 片段再 SMT。失败模型给反例赋值。可靠相对理论公理；完备只在声明的可判定碎片内。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"读写公理翻成人话：先在位置 \\(i\\) 写入 \\(v\\) 再去读，读到的只有两种结果——读的位置正是 \\(i\\) 就得到 \\(v\\)，读的是别的位置 \\(j\\) 就等于原数组在 \\(j\\) 处的旧值。例如 \\(a[1]\\mathrel{:=}5\\) 之后，\\(\\mathrm{read}(a',1)=5\\) 和 \\(\\mathrm{read}(a',2)=\\mathrm{read}(a,2)\\) 各由一条公理直接给出，不需要循环也不需要归纳。")],-1)),a[6]||(a[6]=e("p",null,"与 LWE、数论无关：整数在 SMT 里是线性算术，不是 RSA 模。",-1)),a[7]||(a[7]=e("p",null,"Simplex 处理 QF_LRA；位向量可 bit-blast 成 SAT。数组：读写公理 \\(\\mathrm{read}(\\mathrm{write}(a,i,v),j)\\)。字符串、浮点是后加理论，可判定性各异。量词实例化不完备：助手 hammers 调用 SMT 得到的是「这碎片上 sat/unsat」，不是一阶完备性。与模 \\(pq\\) 密码算术不是同一求解器配置。",-1)),(t(),s(i,null,{default:E(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E5%BE%85%E9%AA%8C%20VC%20%E6%B7%B7%E7%9D%80%E5%A4%9A%E4%B8%AA%E7%90%86%E8%AE%BA%E7%9A%84%E5%8E%9F%E5%AD%90%22%5D%20--%3E%20P%5B%22%E6%8C%89%E7%AD%BE%E5%90%8D%E6%8A%8A%E5%8E%9F%E5%AD%90%E5%88%86%E7%BB%99%E5%90%84%E7%90%86%E8%AE%BA%22%5D%0A%20%20P%20--%3E%20L1%5B%22%E7%BA%BF%E6%80%A7%E7%AE%97%E6%9C%AF%3A%20Simplex%22%5D%0A%20%20P%20--%3E%20L2%5B%22%E6%95%B0%E7%BB%84%E4%B8%8E%E7%AD%89%E5%BC%8F%3A%20%E5%90%8C%E4%BD%99%E9%97%AD%E5%8C%85%22%5D%0A%20%20P%20--%3E%20L3%5B%22%E4%BD%8D%E5%90%91%E9%87%8F%3A%20bit-blast%20%E6%88%90%20SAT%22%5D%0A%20%20L1%20--%3E%20S%5B%22%E5%90%84%E8%87%AA%E7%BB%99%E5%87%BA%E6%A8%A1%E5%9E%8B%E6%88%96%E5%86%B2%E7%AA%81%E6%A0%B8%22%5D%0A%20%20L2%20--%3E%20S%0A%20%20L3%20--%3E%20S%0A%20%20S%20--%3E%20E%7B%22%E5%85%B1%E4%BA%AB%E5%8F%98%E9%87%8F%E7%9A%84%E7%AD%89%E5%BC%8F%E4%B8%A4%E8%BE%B9%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20E%20--%20%22%E5%90%A6%22%20--%3E%20X%5B%22Nelson-Oppen%20%E4%BA%A4%E6%8D%A2%E7%AD%89%E5%BC%8F%20%E7%BB%A7%E7%BB%AD%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20E%20--%20%22%E6%98%AF%22%20--%3E%20OK%5B%22%E5%90%88%E5%B9%B6%E6%A8%A1%E5%9E%8B%20%E5%88%A4%20SAT%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=n('<p><span class="marginnote">术语翻译：bit-blasting（位爆破）就是把一个 \\(n\\) 位的位向量变量摊开成 \\(n\\) 个布尔变量，把加、减、比较按电路门逐位展开成子句，交给普通 SAT 求解。一个 32 位加法大约展开成上百个门的约束——位宽一大，搜索空间按 \\(2^n\\) 涨，这正是正文「规模随位宽」的量化含义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列全部 SMT-LIB 逻辑，不写字符串理论。不把神经网络验证当主线。后课默认：含算术的 VC 走 DPLL(T)。下一课交互证明助手与依值类型，补上 SMT 不覆盖的构造性证明。</p><p>DPLL(T) 让算术、数组、位向量把文字传播回 CDCL。可判定性停在声明的 QF 碎片；量词 E-matching 不完备。VC 生成之后的自动层在此；构造性证明对象下一课助手。</p><p><span class="marginnote">常见误区：把 SMT 当成「能解一切数学」的神器。它只在声明的无量词可判定碎片内保证 sat/unsat 二选一；带量词的一阶公式一般不可判定，Z3 的 E-matching 只是启发式——它「找不出反例」不等于「不存在反例」，拿这个结果当证明要格外小心。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SMT = CDCL + 理论判定/传播。</li><li>无量词稳定理论可 Nelson–Oppen 组合。</li><li>量词靠启发式；一般一阶仍不可判定。</li><li>出处：Nelson and Oppen, 1979；SMT-LIB；Kroening and Strichman。</li></ul>',7))])}const L=A(d,[["render",m]]);export{C as __pageData,L as default};
